-- Costa Rica: ES/DE/FR milestone translations for the 7 milestones in
-- migration 398. Hand-translated, not machine copy-paste. Spanish uses
-- natural Costa Rican/Central American register (e.g. "setiembre" for
-- September, as commonly used in Costa Rica), not a literal
-- back-translation of the English.

-- cr-dgt-r012-2018-announced
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-dgt-r012-2018-announced', 'es', 'La Resolución DGT-R-012-2018 establece el calendario del mandato general de facturación electrónica en Costa Rica', 'Firmada el 19 de febrero de 2018 y publicada en La Gaceta N° 53 (Alcance Digital N° 60) el 20 de marzo de 2018, la Resolución DGT-R-012-2018 ("Obligatoriedad General para el Uso de los Comprobantes Electrónicos") extendió la obligación de facturación electrónica que Costa Rica ya tenía -- vigente para el sector salud y otros servicios profesionales desde enero-mayo de 2018 bajo resoluciones anteriores específicas por sector -- a prácticamente todo el resto de contribuyentes obligados tributariamente, de forma escalonada según el último dígito de la cédula del contribuyente. Quedaron excluidos los contribuyentes del Régimen Simplificado y ciertas entidades públicas o sin fines de lucro. El incumplimiento se vinculó al artículo 83 del Código de Normas y Procedimientos Tributarios.', '["No se requiere ninguna acción para este hito histórico -- establece el calendario que realmente ejecutan las dos olas siguientes", "Si su empresa no está segura de qué ola le correspondió, el calendario se organizó según el último dígito de la cédula del contribuyente -- consulte los hitos siguientes para conocer las fechas exactas"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-dgt-r012-2018-announced', 'de', 'Resolution DGT-R-012-2018 legt den Zeitplan für Costa Ricas allgemeine E-Rechnungspflicht fest', 'Die am 19. Februar 2018 unterzeichnete und am 20. März 2018 in La Gaceta N° 53 (Alcance Digital N° 60) veröffentlichte Resolution DGT-R-012-2018 ("Obligatoriedad General para el Uso de los Comprobantes Electrónicos") weitete Costa Ricas bestehende E-Rechnungspflicht -- bereits seit Januar-Mai 2018 für das Gesundheitswesen und andere freiberufliche Dienstleistungssektoren aufgrund früherer, sektorspezifischer Resolutionen verpflichtend -- auf praktisch alle übrigen steuerpflichtigen Personen aus, gestaffelt nach der letzten Ziffer der Steuerpflichtigen-ID. Beitragszahler des vereinfachten Regimes (Régimen Simplificado) sowie bestimmte staatliche/gemeinnützige Einrichtungen waren ausgenommen. Bei Nichteinhaltung griff Artikel 83 des Código de Normas y Procedimientos Tributarios.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er legt den Zeitplan fest, den die beiden folgenden Wellen tatsächlich umsetzen", "Wenn Ihr Unternehmen nicht sicher ist, welche Welle für Sie galt: Der Zeitplan richtete sich nach der letzten Ziffer Ihrer Steuerpflichtigen-ID -- die genauen Daten finden Sie in den folgenden Meilensteinen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-dgt-r012-2018-announced', 'fr', 'La résolution DGT-R-012-2018 fixe le calendrier de l''obligation générale de facturation électronique au Costa Rica', 'Signée le 19 février 2018 et publiée dans La Gaceta N° 53 (Alcance Digital N° 60) le 20 mars 2018, la résolution DGT-R-012-2018 (« Obligatoriedad General para el Uso de los Comprobantes Electrónicos ») a étendu l''obligation de facturation électronique déjà en vigueur au Costa Rica -- obligatoire pour le secteur de la santé et d''autres services professionnels depuis janvier-mai 2018 en vertu de résolutions antérieures propres à chaque secteur -- à la quasi-totalité des contribuables restants, selon un calendrier échelonné en fonction du dernier chiffre du numéro d''identification du contribuable. Les contribuables du régime simplifié (Régimen Simplificado) et certaines entités publiques ou à but non lucratif en étaient exclus. Le non-respect de cette obligation relevait de l''article 83 du Código de Normas y Procedimientos Tributarios.', '["Aucune action n''est requise pour ce jalon historique -- il établit le calendrier que les deux vagues suivantes mettent réellement en œuvre", "Si votre entreprise n''est pas sûre de la vague qui s''appliquait à elle, le calendrier était organisé selon le dernier chiffre du numéro d''identification du contribuable -- consultez les jalons ci-dessous pour connaître les dates exactes"]');

-- cr-general-mandate-wave1-2018
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-general-mandate-wave1-2018', 'es', 'Entra en vigor la primera ola del mandato general de facturación electrónica en Costa Rica', 'A partir del 1 de setiembre de 2018, bajo el calendario escalonado de la DGT-R-012-2018, los contribuyentes cuya cédula termina en 1, 2 o 3 quedaron legalmente obligados a emitir Comprobantes Electrónicos -- la primera ola del mandato general, después de los proveedores de salud y otros sectores de servicios profesionales que ya estaban obligados desde principios de ese año. Le siguieron dos olas más, el 1 de octubre (cédula terminada en 4, 5 o 6) y el 1 de noviembre de 2018 (cédula terminada en 0, 7, 8 o 9), completando así el despliegue.', '["Si su cédula termina en 1, 2 o 3, confirme que su obligación de facturación electrónica ha estado vigente desde esta fecha", "Si todavía no lo ha hecho, elija ya una solución de facturación -- tanto las herramientas gratuitas de Hacienda como los numerosos proveedores certificados de terceros son opciones válidas"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-general-mandate-wave1-2018', 'de', 'Erste Welle von Costa Ricas allgemeiner E-Rechnungspflicht tritt in Kraft', 'Ab dem 1. September 2018 wurden nach dem gestaffelten Zeitplan der DGT-R-012-2018 Steuerpflichtige, deren ID-Nummer auf 1, 2 oder 3 endet, gesetzlich zur Ausstellung elektronischer Comprobantes verpflichtet -- die erste Welle der allgemeinen Pflicht, nach dem Gesundheitswesen und anderen freiberuflichen Dienstleistungssektoren, die bereits Anfang desselben Jahres verpflichtet worden waren. Zwei weitere Wellen folgten am 1. Oktober (ID endet auf 4, 5 oder 6) und am 1. November 2018 (ID endet auf 0, 7, 8 oder 9) und schlossen damit den Rollout ab.', '["Wenn Ihre Steuerpflichtigen-ID auf 1, 2 oder 3 endet, prüfen Sie, ob Ihre Pflicht zur elektronischen Rechnungsstellung seit diesem Datum aktiv ist", "Wählen Sie jetzt eine Rechnungslösung, falls noch nicht geschehen -- sowohl Haciendas eigene kostenlose Tools als auch zahlreiche zertifizierte Drittanbieter sind gültige Wege"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-general-mandate-wave1-2018', 'fr', 'La première vague de l''obligation générale de facturation électronique du Costa Rica entre en vigueur', 'À compter du 1er septembre 2018, selon le calendrier échelonné de la DGT-R-012-2018, les contribuables dont le numéro d''identification se termine par 1, 2 ou 3 ont été légalement tenus d''émettre des Comprobantes électroniques -- première vague de l''obligation générale, après les prestataires de santé et autres secteurs de services professionnels déjà assujettis depuis le début de la même année. Deux vagues supplémentaires ont suivi, le 1er octobre (numéro se terminant par 4, 5 ou 6) et le 1er novembre 2018 (numéro se terminant par 0, 7, 8 ou 9), achevant ainsi le déploiement.', '["Si votre numéro d''identification se termine par 1, 2 ou 3, vérifiez que votre obligation de facturation électronique est active depuis cette date", "Choisissez dès maintenant une solution de facturation si ce n''est pas déjà fait -- les outils gratuits de Hacienda et de nombreux prestataires tiers certifiés sont tous deux des options valables"]');

-- cr-general-mandate-full-2018
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-general-mandate-full-2018', 'es', 'Se completa el mandato general de facturación electrónica -- todos los contribuyentes restantes deben cumplir', 'A partir del 1 de noviembre de 2018, la última ola del calendario de la DGT-R-012-2018 incorporó a todos los contribuyentes obligados que quedaban, con cédula terminada en 0, 7, 8 o 9, completando así el mandato general que había comenzado con el sector salud y los servicios profesionales a inicios de 2018 y había continuado con las olas de setiembre y octubre. Quedó excluida una lista corta de contribuyentes del Régimen Simplificado y de entidades públicas o sin fines de lucro (únicamente para actividad no comercial). Este es el hito bandera: desde esta fecha, la facturación electrónica se convirtió en la exigencia legal por defecto para prácticamente todas las empresas inscritas en el IVA en Costa Rica, sin importar el monto de sus ingresos.', '["Si su empresa no ha recibido confirmación de que está emitiendo Comprobantes Electrónicos conformes, trate esto como un riesgo activo de incumplimiento, no como un asunto histórico ya resuelto", "Verifique si su caso encaja en alguna de las pocas exenciones que quedan (Régimen Simplificado, o actividad no comercial del sector público o sin fines de lucro) antes de asumir que el mandato le aplica"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-general-mandate-full-2018', 'de', 'Allgemeine E-Rechnungspflicht ist vollständig abgeschlossen -- jeder verbleibende Steuerpflichtige muss sie erfüllen', 'Ab dem 1. November 2018 erfasste die letzte Welle des Zeitplans der DGT-R-012-2018 jeden verbleibenden steuerpflichtigen Steuerzahler, dessen ID auf 0, 7, 8 oder 9 endet, und schloss damit die allgemeine Pflicht ab, die Anfang 2018 mit dem Gesundheitswesen und freiberuflichen Dienstleistungen begonnen und sich über die September- und Oktoberwellen fortgesetzt hatte. Weiterhin ausgenommen blieben Beitragszahler des Régimen Simplificado sowie eine kurze Liste öffentlicher/gemeinnütziger Einrichtungen (nur für nicht-kommerzielle Tätigkeiten). Dies ist der Leitmeilenstein: Ab diesem Datum wurde die elektronische Rechnungsstellung zur gesetzlichen Standardanforderung für praktisch alle mehrwertsteuerpflichtigen Unternehmen in Costa Rica, ohne Umsatzschwelle.', '["Wenn Sie keine Bestätigung erhalten haben, dass Ihr Unternehmen konforme elektronische Comprobantes ausstellt, behandeln Sie dies als aktives Non-Compliance-Risiko, nicht als erledigte Altfrage", "Prüfen Sie, ob Sie unter eine der wenigen verbleibenden Ausnahmen fallen (Régimen Simplificado oder nicht-kommerzielle Tätigkeit im öffentlichen/gemeinnützigen Sektor), bevor Sie davon ausgehen, dass die Pflicht für Sie gilt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-general-mandate-full-2018', 'fr', 'L''obligation générale de facturation électronique s''achève -- tous les contribuables restants doivent s''y conformer', 'À compter du 1er novembre 2018, la dernière vague du calendrier de la DGT-R-012-2018 a fait entrer tous les contribuables assujettis restants, dont le numéro d''identification se termine par 0, 7, 8 ou 9, achevant l''obligation générale entamée avec le secteur de la santé et les services professionnels au début de 2018 et poursuivie lors des vagues de septembre et d''octobre. Une courte liste de contribuables du Régimen Simplificado et d''organismes publics ou à but non lucratif (pour leur seule activité non commerciale) est restée exclue. Il s''agit du jalon phare : à compter de cette date, la facturation électronique est devenue l''exigence légale par défaut pour la quasi-totalité des entreprises assujetties à la TVA au Costa Rica, sans seuil de chiffre d''affaires.', '["Si votre entreprise n''a pas reçu confirmation qu''elle émet des Comprobantes électroniques conformes, considérez cela comme un risque actif de non-conformité, et non comme une question historique déjà réglée", "Vérifiez si vous relevez de l''une des rares exemptions restantes (Régimen Simplificado, ou activité non commerciale du secteur public ou à but non lucratif) avant de présumer que l''obligation vous concerne"]');

-- cr-schema-v44-mandatory-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-schema-v44-mandatory-2025', 'es', 'La versión 4.4 del esquema XML se vuelve obligatoria para todos los comprobantes electrónicos', 'En seguimiento del Decreto N° 44739-H (8 de noviembre de 2024) y de las Resoluciones MH-DGT-RES-0027-2024 y MH-DGT-RES-0001-2025, Hacienda habilitó la adopción voluntaria de la versión 4.4 del esquema de Comprobantes Electrónicos el 1 de abril de 2025, mantuvo una ventana de convivencia en la que eran válidas tanto la v4.3 como la v4.4, y volvió obligatoria la v4.4 a partir del 1 de setiembre de 2025. La nueva versión incorpora códigos de medio de pago (incluyendo SINPE Móvil y plataformas digitales), campos ampliados para contribuyentes no domiciliados, integración con el registro fiscal de bebidas con contenido alcohólico, desgloses tributarios más detallados, y documentación reforzada de exoneraciones y exenciones.', '["Confirme que su software o proveedor de facturación esté certificado contra el esquema v4.4 -- los documentos en v4.3 ya no son válidos desde esta fecha", "Si su empresa maneja pagos por SINPE Móvil, contrapartes no domiciliadas o exoneraciones, verifique que su implementación de la v4.4 realmente capture los nuevos campos obligatorios y no se limite a pasar la validación del esquema"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-schema-v44-mandatory-2025', 'de', 'XML-Schema-Version 4.4 wird für alle elektronischen Belege verpflichtend', 'Im Anschluss an das Dekret N° 44739-H (8. November 2024) sowie die Resolutionen MH-DGT-RES-0027-2024 und MH-DGT-RES-0001-2025 öffnete Hacienda am 1. April 2025 die freiwillige Einführung der Schema-Version 4.4 für Comprobantes Electrónicos, führte eine Koexistenzphase durch, in der sowohl v4.3 als auch v4.4 gültig waren, und machte v4.4 ab dem 1. September 2025 verpflichtend. Die neue Version ergänzt Zahlungsart-Codes (einschließlich SINPE Móvil und digitaler Plattformen), erweiterte Felder für nicht ansässige Steuerpflichtige, die Integration des fiskalischen Registers für alkoholische Getränke, feinere Steueraufschlüsselungen sowie eine verbesserte Dokumentation von Befreiungen und Ausnahmen.', '["Prüfen Sie, ob Ihre Rechnungssoftware oder Ihr Anbieter für Schema v4.4 zertifiziert ist -- v4.3-Dokumente sind ab diesem Datum nicht mehr gültig", "Wenn Ihr Unternehmen SINPE-Móvil-Zahlungen, nicht ansässige Geschäftspartner oder Befreiungen abwickelt, prüfen Sie, ob Ihre v4.4-Implementierung die neuen Pflichtfelder tatsächlich erfasst und nicht nur die Schema-Validierung besteht"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-schema-v44-mandatory-2025', 'fr', 'La version 4.4 du schéma XML devient obligatoire pour tous les comprobantes électroniques', 'Faisant suite au décret N° 44739-H (8 novembre 2024) et aux résolutions MH-DGT-RES-0027-2024 et MH-DGT-RES-0001-2025, Hacienda a ouvert l''adoption volontaire de la version 4.4 du schéma des Comprobantes Electrónicos le 1er avril 2025, a mis en place une période de coexistence durant laquelle les versions v4.3 et v4.4 étaient toutes deux valables, puis a rendu la v4.4 obligatoire à compter du 1er septembre 2025. La nouvelle version ajoute des codes de mode de paiement (dont SINPE Móvil et les plateformes numériques), des champs élargis pour les contribuables non domiciliés, l''intégration au registre fiscal des boissons alcoolisées, une ventilation fiscale plus granulaire, ainsi qu''une documentation renforcée des exonérations et exemptions.', '["Vérifiez que votre logiciel ou prestataire de facturation est certifié pour le schéma v4.4 -- les documents en v4.3 ne sont plus valables à compter de cette date", "Si votre entreprise gère des paiements SINPE Móvil, des contreparties non domiciliées ou des exonérations, vérifiez que votre implémentation de la v4.4 capture réellement les nouveaux champs requis, et ne se contente pas de passer la validation du schéma"]');

-- cr-tribu-cr-launch-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-tribu-cr-launch-2025', 'es', 'Hacienda pone en marcha TRIBU-CR, en sustitución de la plataforma ATV', 'A las 9:00 a.m. del lunes 6 de octubre de 2025, el Ministerio de Hacienda de Costa Rica activó TRIBU-CR (Sistema Integrado de Administración Tributaria), su nueva plataforma tributaria integrada, dando de baja la noche anterior la antigua herramienta gratuita de facturación ATV y lanzando al mismo tiempo una nueva herramienta gratuita de facturación electrónica, TICO FACTURA. La migración movió más de 883 millones de registros en los días previos. El lanzamiento de TRIBU-CR fue la Fase 1 de un despliegue planeado en 9 fases y 28 módulos, con la finalización total prevista para 2027 -- se trata, entonces, del inicio de una transición de plataforma que se extenderá varios años, no de un cambio puntual.', '["Si usted usaba la herramienta gratuita de facturación ATV de Hacienda, confirme que ya migró a TICO FACTURA -- la herramienta anterior se dio de baja la noche previa a la entrada en operación de TRIBU-CR", "Espere que sigan surgiendo inconvenientes conforme se desplieguen las 8 fases restantes de TRIBU-CR hasta 2027 -- consulte directamente la página de Avisos TRIBU-CR de Hacienda en lugar de asumir que el sistema ya es estable"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-tribu-cr-launch-2025', 'de', 'Hacienda führt TRIBU-CR ein und löst damit die ATV-Plattform ab', 'Um 9:00 Uhr am Montag, dem 6. Oktober 2025, aktivierte Costa Ricas Ministerio de Hacienda TRIBU-CR (Sistema Integrado de Administración Tributaria), seine neue integrierte Steuerplattform, stellte das alte kostenlose ATV-Rechnungstool am Vorabend ein und startete gleichzeitig ein neues kostenloses E-Rechnungstool, TICO FACTURA. Bei der Migration wurden in den Tagen zuvor über 883 Millionen Datensätze übertragen. Der Start von TRIBU-CR war Phase 1 eines geplanten neunphasigen Rollouts mit 28 Modulen; die vollständige Fertigstellung ist für 2027 vorgesehen -- es handelt sich also um den Beginn einer mehrjährigen Plattformumstellung, nicht um eine einmalige Umstellung.', '["Wenn Sie das kostenlose ATV-Rechnungstool von Hacienda genutzt haben, prüfen Sie, ob Sie zu TICO FACTURA migriert sind -- das alte Tool wurde am Abend vor dem Start von TRIBU-CR abgeschaltet", "Rechnen Sie mit weiteren Unebenheiten, während die verbleibenden 8 Phasen von TRIBU-CR bis 2027 ausgerollt werden -- verfolgen Sie direkt Haciendas Seite Avisos TRIBU-CR, statt von Stabilität auszugehen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-tribu-cr-launch-2025', 'fr', 'Hacienda lance TRIBU-CR, qui remplace la plateforme ATV', 'À 9h00 le lundi 6 octobre 2025, le Ministerio de Hacienda du Costa Rica a activé TRIBU-CR (Sistema Integrado de Administración Tributaria), sa nouvelle plateforme fiscale intégrée, retirant l''ancien outil de facturation gratuit ATV la veille au soir et lançant simultanément un nouvel outil de facturation électronique gratuit, TICO FACTURA. La migration a déplacé plus de 883 millions d''enregistrements dans les jours précédents. Le lancement de TRIBU-CR constituait la phase 1 d''un déploiement prévu en 9 phases et 28 modules, l''achèvement complet étant visé pour 2027 -- il s''agit donc du début d''une transition de plateforme pluriannuelle, et non d''un basculement ponctuel.', '["Si vous utilisiez l''outil de facturation gratuit ATV de Hacienda, vérifiez que vous avez bien migré vers TICO FACTURA -- l''ancien outil a été retiré la veille au soir du lancement de TRIBU-CR", "Attendez-vous à des difficultés persistantes à mesure que les 8 phases restantes de TRIBU-CR seront déployées jusqu''en 2027 -- suivez directement la page Avisos TRIBU-CR de Hacienda plutôt que de présumer d''une stabilité acquise"]');

-- cr-cedula-cutover-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-cedula-cutover-2026', 'es', 'El nuevo formato alfanumérico de cédula jurídica llega a su fecha de corte de producción en facturación electrónica', 'El Registro Nacional de Costa Rica está migrando del actual formato numérico de cédula jurídica de 6 dígitos (por ejemplo, 3-002-662100), cuya casi un millón de combinaciones posibles está por agotarse para nuevas inscripciones de sociedades, a un nuevo formato alfanumérico (por ejemplo, 3-101-A00001) al amparo del Decreto Ejecutivo 44648-MJ. Las sociedades ya existentes conservan su cédula numérica actual. Para dar soporte a este cambio, Hacienda emitió un parche técnico al esquema v4.4 (con fecha del 22 de abril de 2026) que ajusta los campos de identificación del emisor y del receptor para aceptar caracteres alfanuméricos. Se espera que los sistemas de facturación validen y emitan comprobantes con el nuevo formato de cédula en producción a partir del 1 de noviembre de 2026 -- aunque el cronograma más amplio del despliegue de la nueva cédula se ha descrito en otras fuentes como aún no del todo definido, por lo que esta fecha en particular debe tratarse como una meta prevista y no como un plazo cerrado y confirmado de forma independiente.', '["Si su sistema de facturación valida las cédulas de contribuyente con un patrón fijo de 6 dígitos numéricos, confirme que ya se actualizó para aceptar el nuevo formato alfanumérico de cédula jurídica antes de esta fecha", "Esté atento a los comunicados oficiales de Hacienda en TRIBU-CR para la confirmación final de esta fecha, en lugar de basarse únicamente en reportes secundarios del sector de cumplimiento tributario"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-cedula-cutover-2026', 'de', 'Neues alphanumerisches cédula-jurídica-Format erreicht seinen Produktions-Stichtag für die E-Rechnungsstellung', 'Costa Ricas Nationales Register wechselt vom aktuellen 6-stelligen numerischen cédula-jurídica-Format (z. B. 3-002-662100), dessen rund eine Million möglicher Kombinationen für neue Firmenregistrierungen fast ausgeschöpft sind, zu einem neuen alphanumerischen Format (z. B. 3-101-A00001) gemäß Decreto Ejecutivo 44648-MJ. Bestehende Unternehmen behalten ihre aktuellen numerischen IDs. Um dies zu unterstützen, veröffentlichte Hacienda einen technischen Patch für Schema v4.4 (datiert auf den 22. April 2026), der die Identifikationsfelder von Aussteller/Empfänger so anpasst, dass alphanumerische Zeichen akzeptiert werden. Rechnungssysteme sollen ab dem 1. November 2026 in der Produktion gegen das neue ID-Format validieren und ausstellen -- allerdings wurde der breitere Zeitplan für die Einführung der cédula andernorts als noch nicht vollständig festgelegt beschrieben, weshalb dieses konkrete Datum als erwartete Zielvorgabe und nicht als endgültig fixierte, unabhängig bestätigte Frist zu betrachten ist.', '["Wenn Ihr Rechnungssystem Steuerpflichtigen-IDs mit einem festen 6-stelligen numerischen Muster validiert, prüfen Sie, ob es vor diesem Datum aktualisiert wurde, um das neue alphanumerische cédula-jurídica-Format zu akzeptieren", "Achten Sie auf Haciendas eigene TRIBU-CR-Ankündigungen zur endgültigen Bestätigung dieses Datums, statt sich allein auf sekundäre Berichte aus der Compliance-Branche zu verlassen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-cedula-cutover-2026', 'fr', 'Le nouveau format alphanumérique de cédula jurídica atteint son échéance de bascule en production pour la facturation électronique', 'Le Registre national du Costa Rica passe de l''actuel format numérique à 6 chiffres de la cédula jurídica (par exemple 3-002-662100), dont le près d''un million de combinaisons possibles est presque épuisé pour les nouvelles immatriculations de sociétés, à un nouveau format alphanumérique (par exemple 3-101-A00001) en vertu du Decreto Ejecutivo 44648-MJ. Les sociétés déjà existantes conservent leur identifiant numérique actuel. Pour accompagner ce changement, Hacienda a publié un correctif technique du schéma v4.4 (daté du 22 avril 2026) ajustant les champs d''identification de l''émetteur et du destinataire afin d''accepter des caractères alphanumériques. Les systèmes de facturation devraient valider et émettre selon le nouveau format d''identifiant en production à compter du 1er novembre 2026 -- bien que le calendrier plus large du déploiement de la cédula ait été décrit ailleurs comme n''étant pas encore totalement arrêté ; il convient donc de considérer cette date précise comme un objectif prévu plutôt que comme une échéance figée et confirmée de manière indépendante.', '["Si votre système de facturation valide les numéros d''identification des contribuables selon un modèle fixe à 6 chiffres numériques, vérifiez qu''il a bien été mis à jour pour accepter le nouveau format alphanumérique de la cédula jurídica avant cette date", "Surveillez les annonces officielles de Hacienda sur TRIBU-CR pour la confirmation finale de cette date, plutôt que de vous fier uniquement à des sources secondaires du secteur de la conformité"]');

-- cr-enforcement-package-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-enforcement-package-2026', 'es', 'El Gobierno presenta un paquete de 24 medidas contra el fraude en la facturación electrónica', 'Presentado el 23 de julio de 2026 por la presidenta Laura Fernández, el ministro de Hacienda Rodrigo Chaves y el viceministro Víctor Julio Carvajal, un paquete de 24 medidas de fortalecimiento tributario apunta directamente al fraude en la facturación electrónica -- redes de "facturas falsas" utilizadas para subdeclarar impuestos -- y propone otorgar a Hacienda una nueva potestad legal para suspender administrativamente el derecho de una empresa a facturar electrónicamente, en lugar de depender de un proceso judicial largo. El mismo anuncio reveló las primeras 10 denuncias penales presentadas esa semana contra redes de facturas falsas, de un total de más de 400 investigaciones en curso, con un caso divulgado que involucra más de ₡41 millones en impuestos indebidamente reducidos. Se trata de infraestructura de fiscalización que se suma al mandato ya existente, no de una nueva población que se incorpora por primera vez a la facturación electrónica.', '["Revise desde ya sus controles de facturación y la debida diligencia de proveedores si su empresa tiene algún grado de exposición a proveedores informales o de alto riesgo -- el enfoque declarado de Hacienda está puesto específicamente en las redes de fraude de facturas, no en brechas de cumplimiento rutinarias", "Si Hacienda obtiene la potestad de suspensión administrativa propuesta, trate la pérdida repentina del derecho a facturar electrónicamente como un riesgo operativo real para cualquier empresa vinculada, aunque sea indirectamente, con una contraparte señalada"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-enforcement-package-2026', 'de', 'Regierung stellt 24-Punkte-Maßnahmenpaket gegen betrügerische E-Rechnungsstellung vor', 'Am 23. Juli 2026 von Präsidentin Laura Fernández, Finanzminister Rodrigo Chaves und Vizeminister Víctor Julio Carvajal vorgestellt, zielt ein 24-Punkte-Steuervollzugspaket direkt auf betrügerische elektronische Rechnungsstellung ab -- Netzwerke für "falsche E-Rechnungen", die zur Untererfassung von Steuern genutzt werden -- und schlägt eine neue gesetzliche Befugnis für Hacienda vor, das Recht eines Unternehmens zur elektronischen Rechnungsstellung administrativ auszusetzen, anstatt sich auf ein langwieriges Gerichtsverfahren zu verlassen. Bei derselben Ankündigung wurden die ersten 10 in dieser Woche eingereichten Strafanzeigen gegen Rechnungsbetrugsnetzwerke offengelegt, von mehr als 400 laufenden Ermittlungen, wobei ein bekannt gegebener Fall über 41 Millionen ₡ an unrechtmäßig reduzierter Steuer betraf. Dies ist Vollzugsinfrastruktur, die auf die bestehende Pflicht aufgesetzt wird, keine neue Population, die erstmals in die elektronische Rechnungsstellung einbezogen wird.', '["Überprüfen Sie jetzt Ihre Rechnungskontrollen und Ihre Lieferantenprüfung, wenn Ihr Unternehmen in irgendeiner Form Kontakt zu informellen oder risikobehafteten Lieferanten hat -- Haciendas erklärter Fokus liegt speziell auf Rechnungsbetrugsnetzwerken, nicht auf routinemäßigen Compliance-Lücken", "Sollte Hacienda die vorgeschlagene Befugnis zur administrativen Aussetzung erhalten, behandeln Sie den plötzlichen Verlust des Rechts zur elektronischen Rechnungsstellung als reales operatives Risiko für jedes Unternehmen, das auch nur indirekt mit einer auffällig gewordenen Gegenpartei verbunden ist"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-enforcement-package-2026', 'fr', 'Le gouvernement dévoile un train de 24 mesures contre la fraude à la facturation électronique', 'Présenté le 23 juillet 2026 par la présidente Laura Fernández, le ministre des Finances Rodrigo Chaves et le vice-ministre Víctor Julio Carvajal, un train de 24 mesures de renforcement du contrôle fiscal cible directement la fraude à la facturation électronique -- des réseaux de « fausses factures électroniques » utilisés pour sous-déclarer l''impôt -- et propose de doter Hacienda d''un nouveau pouvoir légal permettant de suspendre administrativement le droit d''une entreprise à facturer électroniquement, plutôt que de recourir à une longue procédure judiciaire. La même annonce a révélé les 10 premières plaintes pénales déposées cette semaine-là contre des réseaux de fausses factures, sur plus de 400 enquêtes en cours, l''un des cas divulgués portant sur plus de 41 millions de ₡ d''impôt indûment réduit. Il s''agit d''une infrastructure de contrôle venant s''ajouter à l''obligation déjà existante, et non d''une nouvelle population entrant pour la première fois dans le champ de la facturation électronique.', '["Passez dès maintenant en revue vos contrôles de facturation et la vérification de vos fournisseurs si votre entreprise est exposée, même faiblement, à des fournisseurs informels ou à risque élevé -- l''accent affiché par Hacienda porte spécifiquement sur les réseaux de fraude à la facture, non sur des manquements de conformité courants", "Si Hacienda obtient le pouvoir de suspension administrative proposé, considérez la perte soudaine du droit à la facturation électronique comme un risque opérationnel réel pour toute entreprise liée, même indirectement, à une contrepartie signalée"]');
